// ============================================
// VALIDATION INPUT - MCP Text to Speech
// ============================================

const input = $input.first().json;
const body = input.body || input;

// Support RFC-014: data in context.* with fallback to root level
const ctx = body.context || {};

const errors = [];

// --- OPTIONAL context fields (for tracing only, no validation errors) ---
const userId = body.user_id || ctx.user_id || null;
const guildId = body.guild_id || ctx.guild_id || null;
const userRequest = body.user_request || ctx.user_request || null;

// --- Required parameters for TTS ---
const text = body.text || ctx.text;

if (!text) {
  errors.push('text is required');
}

// --- Optional parameters with defaults ---
const voice = body.voice || ctx.voice || 'alloy';
const model = body.model || ctx.model || 'tts-1';
const format = body.format || ctx.format || 'mp3';
const speed = body.speed || ctx.speed || 1;
const executionMode = body.execution_mode || ctx.execution_mode || 'online';

// Validate voice option
const validVoices = ['alloy', 'echo', 'fable', 'onyx', 'nova', 'shimmer'];
if (voice && !validVoices.includes(voice)) {
  errors.push(`Invalid voice. Must be one of: ${validVoices.join(', ')}`);
}

// Validate model option
const validModels = ['tts-1', 'tts-1-hd'];
if (model && !validModels.includes(model)) {
  errors.push(`Invalid model. Must be one of: ${validModels.join(', ')}`);
}

// Validate format option
const validFormats = ['mp3', 'opus', 'aac', 'flac', 'wav', 'pcm'];
if (format && !validFormats.includes(format)) {
  errors.push(`Invalid format. Must be one of: ${validFormats.join(', ')}`);
}

// Validate speed range
if (speed < 0.25 || speed > 4.0) {
  errors.push('Speed must be between 0.25 and 4.0');
}

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest
  };
}

return {
  valid: true,
  text: text,
  voice: voice,
  model: model,
  format: format,
  speed: speed,
  execution_mode: executionMode,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest,
  startTime: Date.now()
};

// ============================================
// BUILD VALIDATION ERROR
// ============================================

const input = $input.first().json;

return {
  success: false,
  _trace: {
    service_response: { validation_errors: input.errors },
    provider: 'openai-tts',
    mode: 'error',
    latency_ms: 0,
    user_id: input.user_id,
    guild_id: input.guild_id,
    user_request: input.user_request
  },
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', '),
    http_status: 400
  },
  user_id: input.user_id,
  guild_id: input.guild_id,
  user_request: input.user_request
};

// ============================================
// FORMAT OUTPUT - MCP Text to Speech
// ============================================

const prevData = $('Validate Input').first().json;
const ttsOutput = $input.first().json;

const result = {
  audio_base64: ttsOutput.data,
  format: prevData.format,
  voice: prevData.voice,
  model: prevData.model
};

return {
  success: true,
  data: result,
  meta: {
    provider: 'openai',
    execution_mode: prevData.execution_mode,
    model: prevData.model
  },
  user_id: prevData.user_id,
  guild_id: prevData.guild_id,
  user_request: prevData.user_request,
  _trace: {
    service_response: result,
    provider: 'openai-tts',
    mode: 'success',
    latency_ms: Date.now() - prevData.startTime,
    user_id: prevData.user_id,
    guild_id: prevData.guild_id,
    user_request: prevData.user_request
  }
};

